});
export type orgcard = z.infer<typeof orgcardschema>;

// the composing service is bound by the compiler:
return { id: org.id, name: org.name, membercount } satisfies orgcard; the violation, for contrast // same data, hand-typed, bound to nothing — the shape an agent invents
