examples list-query  list-query consumer shared/libs/list-query  full walkthrough of wiring a list endpoint end-to-end. this mirrors the structure used by `user-organization-mgmt`. goal  ship `get /organizations` returning paginated, sorted organizations with optional search, status, and type filters. 1. validator — `configs/user-organization-mgmt/api/organization.api.ts`  import { z } from "zod";
import { createlistqueryschema } from "@prowd/list-query/server";
import { list_query_defaults } from "@configs/list-query";

export const getorganizationsqueryschema = createlistqueryschema({
  defaults: list_query_defaults,
  sortable: ["name", "createdat"] as const,
  defaultsort: "name",
  searchable: true,
}).extend({
  status: z.enum(["active", "inactive"]).optional(),
  type:   z.enum(["system_admin", "platform_admin", "organization"]).optional(),
});

export type getorganizationsquery = z.infer<typeof getorganizationsqueryschema>; ts {
  page: number;           // default 1
  pagesize: number;       // default 25
  sort: sortspec[];       // default [{ field: "name", direction: "asc" }]
  search?: string;
  status?: "active" | "inactive";
  type?:   "system_admin" | "platform_admin" | "organization";
} ts output type of `getorganizationsquery`: 2. router — `shared/modules/user-organization-mgmt/api/routes/create-organization-router.ts`  .get(
  "/",
  zvalidator("query", validationschemas.getorganizationsquery),
  async (c) => {
    const query = c.req.valid("query");
    const accesscontext = getaccesscontext(c);
    const result = await orgservice.getall(accesscontext, query);
    return c.json(result); // already { rows, total }
  },
) ts no param parsing, no envelope building, no fallback values. the validator applied everything. 3. service — `shared/modules/user-organization-mgmt/api/services/organization.service.ts`  async getall(accesscontext: accesscontext, query: getorganizationsquery) {
  return this.repo.findall(accesscontext, query);
} ts pure passthrough. the service exists so future business logic has a home, but for a read-only paginated list there's nothing to do. 4. repository — `shared/modules/user-organization-mgmt/api/repositories/organization.repository.ts` `whereexpr` is **one** variable used in **two** queries. that's the enforcement mechanism for "scoped count uses the exact same where." the `leftjoin` is present on both the list and the count, matching the filter semantics. `scopefilterbuilder.compile(...).where` is inside `whereexpr`, so the count respects access control identically. import { applypagination, buildorderby } from "@prowd/list-query/server";
import type { listresponse } from "@prowd/list-query";
import { and, count, eq, ilike, sql } from "drizzle-orm";
import * as schema from "../models";

async findall(
  accesscontext: accesscontext,
  query: getorganizationsquery,
): promise<listresponse<organizationlistrow>> {
  const orgverdict = this.engine.resolveforreadupdate(
    accesscontext.effectiveroles, "organization", "read", accesscontext.subjects,
  );
  const org = this.scopefilterbuilder.compile("organization", orgverdict);
  // enrichment view: caller-owned join, no engine call.
  const summary = { where: undefined, select: { /* extra columns from orgsummaryview */ } };

  const whereexpr = and(
    org.where,
    summary.where,
    query.search
      ? ilike(schema.organization.name, `%${query.search}%`)
      : undefined,
    query.status
      ? sql`(${schema.organization.metadata})::jsonb->>'status' = ${query.status}`
      : undefined,
    query.type
      ? eq(schema.organization.type, query.type)
      : undefined,
  );

  const orderby = buildorderby(
    query.sort,
    {
      name:      schema.organization.name,
      createdat: schema.organization.createdat,
    },
    schema.organization.id,
  );

  const base = this.db
    .select({ ...org.select, ...summary.select })
    .from(schema.organization)
    .leftjoin(
      schema.orgsummaryview,
      eq(schema.organization.id, schema.orgsummaryview.organizationid),
    )
    .where(whereexpr);

  const listq = applypagination(
    base.orderby(...orderby),
    query.page,
    query.pagesize,
  );

  const countq = this.db
    .select({ c: count() })
    .from(schema.organization)
    .leftjoin(
      schema.orgsummaryview,
      eq(schema.organization.id, schema.orgsummaryview.organizationid),
    )
    .where(whereexpr); // same whereexpr — never diverge

  const [rows, [{ c }]] = await promise.all([listq, countq]);
  return { rows, total: number(c) };
} ts notice: 5. frontend type — `shared/modules/user-organization-mgmt/web/types.ts`  import type { listresponse } from "@prowd/list-query";

