doc/realtime-brief:
@libs/realtime — developer implementation brief realtime  realtime shared/libs/realtime  **shared real-time transport engine for server→client push.** why "realtime" and not "sse" or "websocket" modules never know or care how events are delivered. they call `push()` on the server and `userealtimechannel()` on the client. the transport is an implementation detail hidden inside this library. if we ever need bidirectional streaming (e.g., collaborative editing), we swap the transport inside `@libs/realtime` — the `push()` function, the `userealtimechannel()` hook, and every module that uses them remain unchanged. this library is named `realtime` because it is **transport-agnostic by design**. the current implementation uses sse (server-sent events), but the api contract is designed so that switching to websockets, long-polling, or any future transport requires **zero changes** in consuming code — modules and apps. the golden rule no module opens its own connection. no module manages reconnection. no module knows about sse. **one connection per user. modules subscribe to channels. the library handles the rest.** // server — any module or app-level code pushes events
import { push } from "@libs/realtime/api";

await push(userid, {
  channel: "notifications",
  event: "new",
  data: { id: "n1", title: "you were invited", ... },
});

// client — each module subscribes to its own channel
import { userealtimechannel } from "@libs/realtime/web";

const { lastevent } = userealtimechannel("notifications"); typescript architecture  shared/libs/realtime/
├── package.json
├── readme.md                    (copy of this brief, expanded)
├── tsconfig.json
└── src/
    ├── index.ts                 (shared types only — both sides import this)
    ├── types.ts                 (core type definitions)
    ├── api/
    │   ├── index.ts             (server-side barrel export)
    │   ├── connection-manager.ts
    │   └── push.ts
    └── web/
        ├── index.ts             (client-side barrel export)
        ├── realtimeprovider.tsx
        └── userealtimechannel.ts architecture › three entry points (same pattern as `@modules/user-organization-mgmt`) `.` — shared types (both server and client) `./api` — server-side only (connection manager, push function) `./web` — client-side only (react provider, hooks) {
  "exports": {
    ".":    "./src/index.ts",
    "./api": "./src/api/index.ts",
    "./web": "./src/web/index.ts"
  }
} json shared types (`src/types.ts`)  /**
 * a realtime event pushed from server to client.
 * this is the transport-agnostic contract.
 */
export interface realtimeevent<t = unknown> {
  /** channel the event belongs to (e.g., "notifications", "conversations") */
  channel: string;
  /** event name within the channel (e.g., "new", "updated", "deleted") */
  event: string;
  /** event payload — module-specific data */
  data: t;
  /** server-assigned timestamp (iso string) */
  timestamp: string;
  /** optional event id for deduplication / resumption */
  id?: string;
}

/**
 * options for the push function.
 */
export interface pushoptions {
  channel: string;
  event: string;
  data: unknown;
}

/**
 * options for connecting to the realtime stream (client-side).
 */
export interface realtimeconfig {
  /** base url of the api (e.g., "http://localhost:3000") */
  baseurl: string;
  /** path to the sse endpoint (default: "/api/realtime/stream") */
  streampath?: string;
  /** auth headers or cookie-based — depends on app auth strategy */
  getheaders?: () => record<string, string> | promise<record<string, string>>;
} typescript server side (`src/api/`) › connection manager (`connection-manager.ts`)  manages active sse connections per user. when a user connects to the stream endpoint, their writable stream is registered. when `push()` is called, the manager writes to all active streams for that user (supports multiple tabs/devices). /**
 * in-memory connection registry.
 * maps userid → set of active writable streams.
 *
 * for single-process deployments (which is what the seed targets),
 * this is sufficient. for multi-process, this would be replaced with
 * redis pub/sub or postgresql listen/notify — but the push() api
 * stays the same.
 */

export interface connectionmanager {
  /** register a new connection for a user */
  add(userid: string, stream: writablestream): void;
  /** remove a connection when it closes */
  remove(userid: string, stream: writablestream): void;
  /** get all active streams for a user */
  getstreams(userid: string): set<writablestream>;
  /** check if a user has any active connections */
  isconnected(userid: string): boolean;
}

export function createconnectionmanager(): connectionmanager; typescript server side (`src/api/`) › push function (`push.ts`)  import type { connectionmanager } from "./connection-manager";
import type { pushoptions, realtimeevent } from "../types";

/**
 * create a push function bound to a connection manager.
 *
 * usage in app wiring:
 *   const manager = createconnectionmanager();
 *   const push = createpush(manager);
 *
 *   // later, in a service or hook:
 *   await push(userid, { channel: "notifications", event: "new", data: {...} });
 */
export function createpush(
  manager: connectionmanager
): (userid: string, options: pushoptions) => promise<void>; typescript server side (`src/api/`) › sse route factory  the library should also export a factory to create the sse endpoint (hono route), so the app just mounts it: import type { connectionmanager } from "./connection-manager";

/**
 * creates a hono route handler for the sse stream endpoint.
 * the app mounts this at its chosen path (e.g., /api/realtime/stream).
 *
 * - requires authenticated user (app applies auth middleware before this)
 * - registers the connection in the manager
 * - keeps the stream open until client disconnects
 * - cleans up on disconnect
 *
 * uses hono's built-in streamsse helper from "hono/streaming".
 */
export function createstreamroute(manager: connectionmanager): honohandler; typescript server side (`src/api/`) › server-side barrel export (`api/index.ts`)  export { createconnectionmanager } from "./connection-manager";
export type { connectionmanager } from "./connection-manager";
export { createpush } from "./push";
export { createstreamroute } from "./stream-route"; typescript client side (`src/web/`) › realtimeprovider (`realtimeprovider.tsx`)  single provider mounted once in the app root. manages one eventsource connection per authenticated user. distributes events to channel subscribers. import type { realtimeconfig, realtimeevent } from "../types";

interface realtimeproviderprops {
  config: realtimeconfig;
  /** whether the user is authenticated — only connect when true */
  enabled: boolean;
  children: react.reactnode;
}

/**
 * mounts once in the app root (alongside userorgmgmtprovider).
 * opens a single sse connection when enabled=true.
 * automatically reconnects on disconnect (sse native behavior).
 * distributes incoming events to channel subscribers via context.
 */
export function realtimeprovider(props: realtimeproviderprops): jsx.element;

/**
 * internal context — not exported to consumers.
 * consumers use userealtimechannel() instead.
 */ typescript client side (`src/web/`) › userealtimechannel hook (`userealtimechannel.ts`)  import type { realtimeevent } from "../types";

interface userealtimechannelresult<t = unknown> {
  /** the most recent event on this channel (null if none received yet) */
  lastevent: realtimeevent<t> | null;
  /** whether the sse connection is currently open */
  connected: boolean;
}

/**
 * subscribe to events on a specific channel.
 * multiple components can subscribe to the same channel.
 * the hook only delivers events matching the given channel name.
 *
 * usage:
 *   const { lastevent, connected } = userealtimechannel<notificationevent>("notifications");
 *
 *   useeffect(() => {
 *     if (lastevent?.event === "new") {
 *       // handle new notification
 *     }
 *   }, [lastevent]);
 */
export function userealtimechannel<t = unknown>(
  channel: string
): userealtimechannelresult<t>; typescript client side (`src/web/`) › client-side barrel export (`web/index.ts`)  export { realtimeprovider } from "./realtimeprovider";
